    trustNoAdvice: 'No tax or investment advice — estimates only.',
    trustTaxRules: 'German, Austrian, Swiss and US tax rules are supported. Check the figures against your tax documents or with a tax adviser.',
    trustInvest: 'The findings are rules of thumb applied to your data, not a recommendation to buy or sell.',
    pvIntro: 'MAERMIN has no server of its own. Apart from loading the app itself (from GitHub Pages or wherever you host it), this page lists everything that leaves your device and where it goes.',
    pvLocalTitle: 'Stays on this device',
    pvLocal1: 'Your transactions, portfolios, settings and every other record are stored in this browser (localStorage and IndexedDB). With encryption at rest switched on - the default for a new vault - your financial records are encrypted with your password (AES-256-GCM); a few settings (tax settings, exchange-rate history, the security log) stay unencrypted.',
    pvLocal2: 'Your password and recovery code never leave the device; nobody can reset them for you.',
    pvLocal3: 'The security log stays on the device. There is no analytics, telemetry or tracking, and the fonts are part of the app.',
    pvLocal4: 'Backups and exports are files you save yourself; MAERMIN does not upload them.',
    pvWorkerTitle: 'Your Cloudflare Worker',
    pvWorker1: 'The Worker runs in your own Cloudflare account. It receives the symbols of your holdings and your search terms, and fetches prices, history, dividends, fund data and news for them from Yahoo Finance and CoinGecko, and the CS2 price list.',
    pvWorker2: 'It caches the answers, for up to 30 days (company profiles). Amounts and quantities are not sent.',
    pvDirectTitle: 'Requests from your browser to other services',
    pvDirect1: 'CoinGecko image server: coin icons in the symbol search.',
    pvDirect2: 'open.er-api.com / ExchangeRate-API: exchange rates, without any portfolio data.',
    pvDirect3: 'unpkg.com (React, on the first start and after an update; otherwise from the offline cache) and cdnjs.cloudflare.com (PDF tools, on the first PDF export or import): program code, version-pinned and integrity-checked.',
    pvDirect4: 'Logos and pictures load from Yahoo, CoinGecko and the Steam CDN, so those services see which ones you view.',
    pvOptTitle: 'Only if you turn it on',
    pvSync: 'Cloud sync: your Worker stores your data encrypted on your device, under an anonymous account id. It cannot read it.',
    pvShare: 'Share & Compare: a redacted snapshot (percentages and scores, no amounts or quantities) is stored by your Worker for 90 days, plus an anonymous aggregate for the comparison.',
    pvExchange: 'Exchange connections: your Worker relays each request to the exchange. The API key travels with every request (Binance: the request is signed in your browser and the secret stays here). Keys are stored encrypted in your vault.',

