    trustInvest: 'Die Hinweise sind Faustregeln, angewandt auf deine Daten – keine Empfehlung zum Kauf oder Verkauf.',
    pvIntro: 'MAERMIN hat keinen eigenen Server. Abgesehen vom Laden der App selbst (von GitHub Pages oder wo du sie hostest) listet diese Seite alles, was dein Gerät verlässt, und wohin es geht.',
    pvLocalTitle: 'Bleibt auf diesem Gerät',
    pvLocal1: 'Deine Transaktionen, Portfolios, Einstellungen und alle anderen Daten liegen in diesem Browser (localStorage und IndexedDB). Mit eingeschalteter Verschlüsselung im Ruhezustand – Standard für einen neuen Tresor – sind deine Finanzdaten mit deinem Passwort verschlüsselt (AES-256-GCM); einige Einstellungen (Steuereinstellungen, Wechselkursverlauf, Sicherheitsprotokoll) bleiben unverschlüsselt.',
    pvLocal2: 'Passwort und Wiederherstellungscode verlassen nie das Gerät; niemand kann sie für dich zurücksetzen.',
    pvLocal3: 'Das Sicherheitsprotokoll bleibt auf dem Gerät. Es gibt keine Analyse, keine Telemetrie und kein Tracking; die Schriften sind Teil der App.',
